/**
 * VIBEFIELD'S MARK AT REST, for the press's back (CS-D6 C; DESIGN.md §5 "the press"). A marked copy: the band's edge, the
 * near strand's cover and the crossing's hole are the design kit's living mark at rest, path for path
 * (packages/design-kit/src/living-mark/living-mark-light.svg, generated by tooling/splash/living-mark.mjs; the kit
 * exports it only as an animated SVG). `card-press.test` holds every path to that file, so the two cannot drift.
 * The lights ride the band's one edge at their places of 1000, in the kit's strokes.
 */

export const BACK_MARK = {
  box: { x: 1500, y: 1500, w: 9900, h: 4400 },
  edge: "M11115 3410c30 486-110 975-395 1319s-714 533-1192 537s-1001-162-1527-410s-1060-576-1591-896s-1062-631-1583-858s-1035-366-1503-359s-888 167-1177 453s-445 695-431 1099s197 797 509 1045s743 348 1214 281s981-294 1492-619s1025-744 1534-1168s1015-851 1508-1182s975-562 1405-620s799 59 1071 324s446 687 467 1127s-116 883-374 1178s-627 447-1064 454s-942-130-1466-354s-1066-530-1605-828s-1075-589-1591-796s-1015-328-1453-319s-819 146-1090 399s-424 625-420 995s163 729 437 956s661 323 1100 260s928-283 1423-604s1001-739 1504-1165s1007-859 1508-1201s1000-590 1474-661s923 48 1254 350s533 776 562 1263z",
  cover:
    "M5841 4344c209-165 417-337 624-510s414-346 620-513L6932 3141c-205 170-410 344-615 518s-410 346-615 511z",
  hole: "M1400 1400h10100v4600h-10100zM5826 4325c138-110 277-223 416-338s276-229 414-344s276-229 413-341L6948 3160c-137 113-273 228-410 344s-273 232-410 347s-274 229-410 339z",
  /** each light: its colour and its place along the edge, of 1000 */
  lights: [
    ["#FF0054", 473.28],
    ["#00F59B", 157],
    ["#083CFF", 795.69],
  ] as ReadonlyArray<readonly [string, number]>,
  /** each light's strokes: width (box units), opacity, dash (of 1000), the dash's offset past the light's place */
  strokes: [
    [170.01, 0.1334, 80.05, 40.02],
    [170.01, 0.154, 70.53, 35.27],
    [170.01, 0.182, 60.06, 30.03],
    [40.48, 0.5, 82.03, 41.01],
    [40.48, 1, 69.92, 34.96],
  ] as ReadonlyArray<readonly [number, number, number, number]>,
} as const;

type Ctx2D = CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D;

/** The points along a path, for its length: the commands the kit's paths use (M L H V C S Z, either case), every cubic
 * flattened in 24 steps. No DOM, so every place measures it the same. PURE. */
export function pathPoints(d: string): Array<readonly [number, number]> {
  const tok = d.match(/[MmLlHhVvCcSsZz]|-?\d*\.?\d+(?:e[-+]?\d+)?/g) ?? [];
  const pts: Array<readonly [number, number]> = [];
  let i = 0;
  let cmd = "";
  let x = 0;
  let y = 0;
  let sx = 0;
  let sy = 0;
  let c2x = 0;
  let c2y = 0;
  const num = (): number => Number(tok[i++]);
  const cubic = (x1: number, y1: number, x2: number, y2: number, x3: number, y3: number): void => {
    for (let k = 1; k <= 24; k += 1) {
      const t = k / 24;
      const u = 1 - t;
      pts.push([
        u * u * u * x + 3 * u * u * t * x1 + 3 * u * t * t * x2 + t * t * t * x3,
        u * u * u * y + 3 * u * u * t * y1 + 3 * u * t * t * y2 + t * t * t * y3,
      ]);
    }
    c2x = x2;
    c2y = y2;
    x = x3;
    y = y3;
  };
  while (i < tok.length) {
    const t = tok[i] ?? "";
    if (/[A-Za-z]/.test(t)) {
      cmd = t;
      i += 1;
    }
    const rel = cmd === cmd.toLowerCase();
    const ox = rel ? x : 0;
    const oy = rel ? y : 0;
    switch (cmd.toUpperCase()) {
      case "M":
        x = ox + num();
        y = oy + num();
        sx = x;
        sy = y;
        pts.push([x, y]);
        cmd = rel ? "l" : "L";
        break;
      case "L":
        x = ox + num();
        y = oy + num();
        pts.push([x, y]);
        c2x = x;
        c2y = y;
        break;
      case "H":
        x = ox + num();
        pts.push([x, y]);
        c2x = x;
        c2y = y;
        break;
      case "V":
        y = oy + num();
        pts.push([x, y]);
        c2x = x;
        c2y = y;
        break;
      case "C": {
        const x1 = ox + num();
        const y1 = oy + num();
        const x2 = ox + num();
        const y2 = oy + num();
        const x3 = ox + num();
        const y3 = oy + num();
        cubic(x1, y1, x2, y2, x3, y3);
        break;
      }
      case "S": {
        const r1x = 2 * x - c2x;
        const r1y = 2 * y - c2y;
        const x2 = ox + num();
        const y2 = oy + num();
        const x3 = ox + num();
        const y3 = oy + num();
        cubic(r1x, r1y, x2, y2, x3, y3);
        break;
      }
      case "Z":
        x = sx;
        y = sy;
        pts.push([x, y]);
        c2x = x;
        c2y = y;
        break;
      default:
        i += 1;
    }
  }
  return pts;
}

let MARK_LENGTH = 0;

/** The band's edge's length, box units, measured once. */
export function markLength(): number {
  if (MARK_LENGTH > 0) return MARK_LENGTH;
  const p = pathPoints(BACK_MARK.edge);
  let sum = 0;
  for (let k = 1; k < p.length; k += 1) {
    const a = p[k - 1];
    const b = p[k];
    if (a !== undefined && b !== undefined) sum += Math.hypot(b[0] - a[0], b[1] - a[1]);
  }
  MARK_LENGTH = sum;
  return sum;
}

export interface MarkPaint {
  /** the band's fill, or nothing to leave it out */
  readonly band?: string;
  /** the band's hairline, in the context's units */
  readonly hair?: number;
  /** the lights' strength: 0 for none, 1 the icon's */
  readonly lights?: number;
  /** a colour for a light, so a mask can draw the lights in its own channel */
  readonly lightInk?: (hex: string, alpha: number) => string;
  /** the soft strokes' width against the kit's (the icon's is about 2) */
  readonly glow?: number;
  /** the cores' width against the kit's */
  readonly core?: number;
}

/** The mark centred on (cx, cy), the ∞ `width` wide, in the context's current units. */
export function drawMark(
  ctx: Ctx2D,
  cx: number,
  cy: number,
  width: number,
  o: MarkPaint = {},
): void {
  const { box } = BACK_MARK;
  const k = width / (box.w * 0.94);
  ctx.save();
  ctx.translate(cx - (box.x + box.w / 2) * k, cy - (box.y + box.h / 2) * k);
  ctx.scale(k, k);
  const edge = new Path2D(BACK_MARK.edge);
  if (o.band !== undefined) {
    const cover = new Path2D(BACK_MARK.cover);
    ctx.fillStyle = o.band;
    ctx.strokeStyle = o.band;
    ctx.lineJoin = "round";
    ctx.lineWidth = (o.hair ?? 0.5) / k;
    ctx.fill(edge, "evenodd");
    ctx.stroke(edge);
    ctx.fill(cover);
    ctx.stroke(cover);
  }
  const strength = o.lights ?? 0;
  if (strength > 0) {
    ctx.save();
    const length = markLength();
    const dash = (d: number, at: number, add: number): void => {
      ctx.setLineDash([(d * length) / 1000, ((1000 - d) * length) / 1000]);
      ctx.lineDashOffset = ((at + add) * length) / 1000;
    };
    // the soft glow is a stroke drawn far off whose shadow alone lands on the band, so it fades smoothly at this size
    const px = Math.abs(ctx.getTransform().a) || 1;
    const OFF = 20000;
    const [w0, , d0, add0] = BACK_MARK.strokes[0] ?? [0, 0, 0, 0];
    for (const [hex, at] of BACK_MARK.lights) {
      const gw = w0 * (o.glow ?? 2);
      ctx.save();
      ctx.lineCap = "butt";
      ctx.lineWidth = gw * 0.8;
      ctx.strokeStyle = "#000";
      ctx.shadowColor = o.lightInk ? o.lightInk(hex, 1) : hex;
      ctx.shadowBlur = gw * 0.34 * px;
      ctx.shadowOffsetX = OFF;
      ctx.globalAlpha = Math.min(1, 0.92 * strength);
      ctx.translate(-OFF / px, 0);
      dash(d0 * 0.9, at, add0 * 0.9);
      ctx.stroke(edge);
      ctx.restore();
      // the cores: the kit's two, a hair wider so they hold at a card's size
      ctx.lineCap = "round";
      for (const [w, a, d, add] of BACK_MARK.strokes.slice(3)) {
        ctx.strokeStyle = o.lightInk ? o.lightInk(hex, a) : hex;
        ctx.globalAlpha = Math.min(1, a * strength);
        ctx.lineWidth = w * (o.core ?? 1.25);
        dash(d, at, add);
        ctx.stroke(edge);
      }
    }
    ctx.setLineDash([]);
    ctx.restore();
  }
  ctx.restore();
}
